+// API keys, roles and the audit log. Keys live in `apiKeys` as
+// { key, name, role }; every request that changes data leaves an entry in
+// `audit` (docs/DATA.md).
+import { createHash, timingSafeEqual } from "node:crypto";
+
+/** Roles from least to most allowed; each may do what the ones before it may. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The key record whose secret is `secret`, or null. */
+export function findKey(store, secret) {
+  if (typeof secret !== "string" || secret === "") return null;
+  const want = digest(secret);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && timingSafeEqual(digest(k.key), want) && ROLES.includes(k.role)) found = k;
+  }
+  return found;
+}
+
+/** True when `role` may do what needs at least `needed`. */
+export function allows(role, needed) {
+  const have = ROLES.indexOf(role);
+  return have >= 0 && have >= ROLES.indexOf(needed);
+}
+
+/** Appends an audit entry { id, at, key, method, path, status } and returns it. */
+export function recordAudit(store, { key, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function auditLog(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.at.localeCompare(a.at) || b.id - a.id);
+}
