new file mode 100644
index 0000000..51c168b
--- /dev/null
+++ b/tests/access.test.js
@@ -0,0 +1,54 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, as, NOW } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { handle } = app();
+  const none = await handle({ path: "/items", headers: {} });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const unknown = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(unknown.status, 401);
+  const notBearer = await handle({ path: "/items", headers: { authorization: "Basic abc" } });
+  assert.equal(notBearer.status, 401);
+});
+
+test("viewers may only read", async () => {
+  const { handle, store } = app();
+  assert.equal((await handle({ path: "/items", headers: as("viewer") })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: as("viewer") });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks may cook, waste, log temperatures and count, nothing else", async () => {
+  const { handle } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  const h = as("cook");
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: h })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", body: { qty: 0.5 }, headers: h })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 }, headers: h })).status, 201);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 }, headers: h })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: h })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "fridge" }, headers: h })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [] }, headers: h })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: h })).status, 403);
+});
+
+test("changes are audited and only managers read the audit", async () => {
+  const { handle } = app();
+  await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 }, headers: as("cook") });
+  await handle({ method: "POST", path: "/orders/1/send", headers: as("viewer") });
+  await handle({ path: "/items", headers: as("manager") });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: {} });
+  assert.equal((await handle({ path: "/audit", headers: as("viewer") })).status, 403);
+  const log = await handle({ path: "/audit" });
+  assert.equal(log.status, 200);
+  const at = new Date(NOW).toISOString();
+  assert.deepEqual(log.body.map(({ id, ...e }) => e), [
+    { at, key: "front-of-house", method: "POST", path: "/orders/1/send", status: 403 },
+    { at, key: "line-cook", method: "POST", path: "/temperatures", status: 201 },
+  ]);
+});
